<script setup lang="ts">
import { computed, nextTick, ref, watch } from "vue";
import { open as openFile } from "@tauri-apps/plugin-dialog";
import type { HisenseProfile } from "../types/hisense";
const props=defineProps<{open:boolean;profiles:Record<string,HisenseProfile>;enabled:boolean;fixed:string|null;editing:string;activeName:string}>();
const emit=defineEmits<{close:[];change:[profiles:Record<string,HisenseProfile>];settings:[enabled:boolean,fixed:string|null];select:[id:string]}>();
const search=ref(""),draft=ref<{id:string|null;name:string;process_name:string}|null>(null),message=ref(""),removeId=ref<string|null>(null),root=ref<HTMLElement|null>(null);
const rows=computed(()=>Object.entries(props.profiles).filter(([,p])=>`${p.name} ${p.process_name}`.toLowerCase().includes(search.value.toLowerCase())));
let previousFocus:HTMLElement|null=null;
function close(){emit("close");}
function create(){draft.value={id:null,name:"",process_name:""};message.value="";}
async function browse(){try{const path=await openFile({multiple:false,filters:[{name:"应用程序",extensions:["exe"]}]});if(typeof path==="string"&&draft.value){const name=path.split(/[\\/]/).pop()!;draft.value.process_name=name;if(!draft.value.name)draft.value.name=name.replace(/\.exe$/i,"");}}catch(e){message.value=String(e);}}
function save(){const d=draft.value;if(!d)return;const name=d.name.trim(),process_name=d.process_name.trim().toLowerCase();if(!name||name.length>60||!/^[^\\/:*?"<>|\0]+\.exe$/i.test(process_name)){message.value="请输入应用名称和进程名，例如 chrome.exe；也可以浏览选择程序。";return;}if(Object.entries(props.profiles).some(([id,p])=>id!==d.id&&p.enabled&&p.process_name.toLowerCase()===process_name)){message.value="这个应用已有启用的配置，请编辑原配置。";return;}const id=d.id||crypto.randomUUID(),old=props.profiles[id];emit("change",{...props.profiles,[id]:old?{...old,name,process_name}:{name,process_name,enabled:true,button_bindings:{},long_press_bindings:{},multi_click_bindings:{}}});draft.value=null;emit("select",id);}
function toggle(id:string){const p=props.profiles[id];emit("change",{...props.profiles,[id]:{...p,enabled:!p.enabled}});if(p.enabled&&props.fixed===id)emit("settings",props.enabled,null);}
function remove(id:string){if(removeId.value!==id){removeId.value=id;return;}const next={...props.profiles};delete next[id];emit("change",next);if(props.fixed===id)emit("settings",props.enabled,null);if(props.editing===id)emit("select","default");removeId.value=null;}
function keyboard(e:KeyboardEvent){if(e.key==="Escape"){e.preventDefault();close();}if(e.key==="Tab"&&root.value){const nodes=[...root.value.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled])')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===root.value)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
watch(()=>props.open,async open=>{if(open){previousFocus=document.activeElement as HTMLElement;draft.value=null;search.value="";await nextTick();root.value?.focus();}else previousFocus?.focus();});
</script>

<template>
  <div v-if="open" class="profile-backdrop" @click.self="close"><section ref="root" class="profile-dialog" role="dialog" aria-modal="true" aria-labelledby="profile-title" tabindex="-1" @keydown="keyboard">
    <header><div><h2 id="profile-title">游戏与应用配置</h2><p>同一个遥控按键，在不同应用里执行不同功能。</p></div><button aria-label="关闭应用配置" @click="close">×</button></header>
    <div class="profile-body">
      <section class="switching"><div><h3>配置文件切换</h3><p>按前台应用自动切换；固定配置会覆盖自动匹配。</p></div><label><input type="checkbox" :checked="enabled" aria-label="启用配置文件切换" @change="emit('settings',($event.target as HTMLInputElement).checked,fixed)" />启用配置文件切换</label><label>固定使用<select :value="fixed||''" :disabled="!enabled" aria-label="固定使用配置文件" @change="emit('settings',enabled,($event.target as HTMLSelectElement).value||null)"><option value="">无 · 按应用自动切换</option><option value="default">桌面默认</option><option v-for="[id,p] in Object.entries(profiles)" :key="id" :value="id" :disabled="!p.enabled">{{ p.name }}</option></select></label><small>当前生效：{{ activeName }}。切换时会在屏幕左上角提示。</small></section>
      <div class="profile-tools"><input v-model="search" aria-label="搜索应用配置" placeholder="搜索游戏或应用程序" /><button class="primary" @click="create">＋ 添加游戏和应用程序</button></div>
      <form v-if="draft" class="profile-form" @submit.prevent="save"><label>应用名称<input v-model="draft.name" maxlength="60" aria-label="应用配置名称" placeholder="例如 Chrome" /></label><label>进程名<input v-model="draft.process_name" maxlength="120" aria-label="应用进程名" placeholder="chrome.exe" /></label><button type="button" @click="browse">浏览程序</button><button class="primary" type="submit">保存配置</button><button type="button" @click="draft=null">取消</button><p>只保存程序文件名，不修改程序本身。未单独设置的遥控按键继承桌面默认。</p></form>
      <p v-if="message" class="message" role="status">{{ message }}</p>
      <div class="profile-grid"><article :class="{selected:editing==='default'}"><div class="app-icon">⌂</div><h3>桌面默认</h3><p>没有匹配应用时使用</p><button @click="emit('select','default');close()">编辑按键</button></article><article v-for="[id,p] in rows" :key="id" :class="{selected:editing===id,disabled:!p.enabled}"><div class="app-icon">{{ p.name.slice(0,1).toUpperCase() }}</div><h3>{{ p.name }}</h3><p>{{ p.process_name }}</p><small>{{ Object.keys(p.button_bindings).length }} 个独立按键 · {{ p.enabled?'已启用':'已停用' }}</small><div class="profile-actions"><button @click="emit('select',id);close()">编辑按键</button><button @click="draft={id,name:p.name,process_name:p.process_name}">设置</button><button @click="toggle(id)">{{ p.enabled?'停用':'启用' }}</button><button class="danger" @click="remove(id)">{{ removeId===id?'确认删除':'删除' }}</button></div></article></div>
    </div>
  </section></div>
</template>

<style scoped>
.profile-backdrop{position:fixed;inset:0;z-index:3450;background:var(--overlay);padding:24px;display:grid;place-items:center}.profile-dialog{width:min(1000px,calc(100vw - 48px));max-height:calc(100dvh - 48px);background:var(--card-bg);color:var(--text);border:1px solid var(--border);border-radius:16px;box-shadow:var(--dialog-shadow);overflow:hidden;display:flex;flex-direction:column}header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:22px 24px;border-bottom:1px solid var(--border)}h2{margin:0;font-size:20px}h3{margin:0;font-size:14px}p,small{font-size:12px;color:var(--text-secondary);line-height:1.7}header p{margin:6px 0 0}header>button{font-size:24px;padding:3px 12px}.profile-body{overflow:auto;min-height:0;padding:24px}button,input,select{font:inherit;color:var(--text);background:var(--card-bg);border:1px solid var(--border);border-radius:9px;padding:8px 11px;font-size:12px;box-sizing:border-box}button{cursor:pointer}button:hover,article.selected{border-color:var(--primary)}button.primary{background:var(--primary);border-color:var(--primary);color:white}.switching{border:1px solid var(--border);background:var(--surface-soft);border-radius:12px;padding:18px;display:grid;grid-template-columns:1fr 1fr;gap:12px 24px;align-items:center}.switching p{margin:6px 0 0}.switching label{font-size:12px;display:flex;align-items:center;gap:9px}.switching select{flex:1;min-width:0}.switching small{grid-column:1/-1}.profile-tools{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:22px 0}.profile-tools input{width:260px}.profile-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:14px}.profile-grid article{padding:18px;border:1px solid var(--border);border-radius:13px;min-width:0}.profile-grid article.selected{background:color-mix(in srgb,var(--primary) 5%,var(--card-bg));border-color:var(--primary)}article.disabled{opacity:.6}.app-icon{height:80px;background:var(--surface-soft);display:grid;place-items:center;border-radius:10px;color:var(--primary);font-size:30px;font-weight:700;margin-bottom:16px}article p{margin:7px 0;overflow-wrap:anywhere}.profile-actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:15px}.profile-grid small{display:block}.danger{color:var(--danger)}.profile-form{display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end;border:1px solid var(--border);border-radius:11px;padding:16px;margin-bottom:20px}.profile-form label{display:grid;gap:7px;font-size:12px;flex:1;min-width:170px}.profile-form input{width:100%}.profile-form p{flex-basis:100%;margin:3px 0 0}.message{color:var(--danger)}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--primary);outline-offset:2px}@media(max-width:700px){.switching{grid-template-columns:1fr}.profile-body{padding:16px}.profile-tools{flex-wrap:wrap}.profile-tools input{width:100%}}
</style>
